const API_BASE_URL = "http://127.0.0.1:8000";

export async function investigateIncident(incidentId) {
  const response = await fetch(
    `${API_BASE_URL}/ai/root-cause/${incidentId}`,
    {
      method: "POST",
      headers: {
        Accept: "application/json",
      },
    }
  );

  if (!response.ok) {
    throw new Error(`Backend returned ${response.status}`);
  }

  return await response.json();
}

export async function analyzeDeployments(incidentId = 1) {
  const response = await fetch(
    `${API_BASE_URL}/ai/analyze-deployments/${incidentId}`,
    {
      method: "POST",
      headers: {
        Accept: "application/json",
      },
    }
  );

  if (!response.ok) {
    throw new Error(`Backend returned ${response.status}`);
  }

  return await response.json();
}

export async function analyzeLogs(incidentId = 1) {
  const response = await fetch(
    `${API_BASE_URL}/ai/analyze-logs/${incidentId}`,
    {
      method: "POST",
      headers: {
        Accept: "application/json",
      },
    }
  );

  if (!response.ok) {
    throw new Error(`Backend returned ${response.status}`);
  }

  return await response.json();
}

export async function analyzeRootCause(incidentId) {
  return investigateIncident(incidentId);
}
